        expr = self._parse_expr()
        self._expect("OP", ";")
        return LetStmt(ident.text, expr, kw.offset)

    def _parse_assign(self) -> AssignStmt:
        ident = self._expect("IDENT")
        self._expect("OP", "=")
        expr = self._parse_expr()
        self._expect("OP", ";")
        return AssignStmt(ident.text, expr, ident.offset)

