            tok = self._peek()
            if tok is not None and tok.kind == "KEYWORD" and tok.text == "and":
                self._advance()
                right = self._parse_not()
                left = LogicOp("and", left, right, tok.offset)
            else:
                return left

    def _parse_not(self) -> Expr:
        tok = self._peek()
