            self._advance()
            expr = self._parse_expr()
            self._expect("OP", ")")
            return expr
        raise ParseError(f"Unexpected token {tok.text!r} in expression", tok.offset)


def parse(src: str) -> object:
    tokens = tokenize(src)
    return _Parser(tokens, len(src)).parse_program()

