from __future__ import annotations

from microvm.parser import (
    AssignStmt,
    BinOp,
    BlockStmt,
    Expr,
    IfStmt,
    LetStmt,
    Literal,
    LogicOp,
    PrintStmt,
    ProgramAST,
    Stmt,
    UnaryOp,
    WhileStmt,
)


def _is_number(val: object) -> bool:
    return type(val) in (int, float)


def _fold_unary(node: UnaryOp, operand: Expr) -> Expr:
    if not isinstance(operand, Literal):
        return UnaryOp(node.op, operand, node.offset)
    val = operand.value
    if node.op == "-" and _is_number(val):
        return Literal(-val, node.offset)  # type: ignore[operator]
    if node.op == "not" and type(val) is bool:
        return Literal(not val, node.offset)
    return UnaryOp(node.op, operand, node.offset)


def _fold_arith(op: str, lv: object, rv: object, offset: int) -> Literal | None:
    if op == "+" and type(lv) is str and type(rv) is str:
        return Literal(lv + rv, offset)
    if not (_is_number(lv) and _is_number(rv)):
        return None
    if op == "+":
        return Literal(lv + rv, offset)  # type: ignore[operator]
    if op == "-":
        return Literal(lv - rv, offset)  # type: ignore[operator]
    if op == "*":
        return Literal(lv * rv, offset)  # type: ignore[operator]
    if op == "/":
        if rv == 0:
            return None
        return Literal(float(lv) / float(rv), offset)  # type: ignore[arg-type]
    if op == "%":
        if type(lv) is int and type(rv) is int and rv != 0:
            return Literal(lv % rv, offset)
    return None


def _fold_compare(op: str, lv: object, rv: object, offset: int) -> Literal | None:
    if op in ("==", "!="):
        if _is_number(lv) and _is_number(rv):
            eq = lv == rv
        elif type(lv) is type(rv):
            eq = lv == rv
        else:
            eq = False
        return Literal(eq if op == "==" else not eq, offset)
    if (_is_number(lv) and _is_number(rv)) or (type(lv) is str and type(rv) is str):
        if op == "<":
            return Literal(lv < rv, offset)  # type: ignore[operator]
        if op == "<=":
            return Literal(lv <= rv, offset)  # type: ignore[operator]
        if op == ">":
            return Literal(lv > rv, offset)  # type: ignore[operator]
        if op == ">=":
            return Literal(lv >= rv, offset)  # type: ignore[operator]
    return None


def _fold_binop(node: BinOp, left: Expr, right: Expr) -> Expr:
    if isinstance(left, Literal) and isinstance(right, Literal):
        lv, rv = left.value, right.value
        res = (
            _fold_arith(node.op, lv, rv, node.offset)
            if node.op in ("+", "-", "*", "/", "%")
            else _fold_compare(node.op, lv, rv, node.offset)
        )
        if res is not None:
            return res
    return BinOp(node.op, left, right, node.offset)


def _fold_logic(node: LogicOp, left: Expr, right: Expr) -> Expr:
    if isinstance(left, Literal) and type(left.value) is bool:
        if node.op == "and" and left.value is False:
            return Literal(False, node.offset)
        if node.op == "or" and left.value is True:
            return Literal(True, node.offset)
        if isinstance(right, Literal) and type(right.value) is bool:
            if node.op == "and":
                return Literal(left.value and right.value, node.offset)
            return Literal(left.value or right.value, node.offset)
    return LogicOp(node.op, left, right, node.offset)


def _fold_expr(expr: Expr) -> Expr:
    if isinstance(expr, UnaryOp):
        return _fold_unary(expr, _fold_expr(expr.operand))
    if isinstance(expr, BinOp):
        return _fold_binop(expr, _fold_expr(expr.left), _fold_expr(expr.right))
    if isinstance(expr, LogicOp):
        return _fold_logic(expr, _fold_expr(expr.left), _fold_expr(expr.right))
    return expr


def _fold_stmt(stmt: Stmt) -> Stmt:
    if isinstance(stmt, LetStmt):
        return LetStmt(stmt.name, _fold_expr(stmt.expr), stmt.offset)
    if isinstance(stmt, AssignStmt):
        return AssignStmt(stmt.name, _fold_expr(stmt.expr), stmt.offset)
    if isinstance(stmt, PrintStmt):
        return PrintStmt(_fold_expr(stmt.expr), stmt.offset)
    if isinstance(stmt, BlockStmt):
        return BlockStmt([_fold_stmt(s) for s in stmt.stmts], stmt.offset)
    if isinstance(stmt, IfStmt):
        cond = _fold_expr(stmt.cond)
        then_b = _fold_stmt(stmt.then_block)
        assert isinstance(then_b, BlockStmt)
        else_b = _fold_stmt(stmt.else_branch) if stmt.else_branch is not None else None
        assert else_b is None or isinstance(else_b, (BlockStmt, IfStmt))
        return IfStmt(cond, then_b, else_b, stmt.offset)
    if isinstance(stmt, WhileStmt):
        cond = _fold_expr(stmt.cond)
        body = _fold_stmt(stmt.body)
        assert isinstance(body, BlockStmt)
        return WhileStmt(cond, body, stmt.offset)
    return stmt


def fold_constants(node: object) -> object:
    if isinstance(node, ProgramAST):
        return ProgramAST([_fold_stmt(s) for s in node.stmts])
    if isinstance(node, (LetStmt, AssignStmt, PrintStmt, BlockStmt, IfStmt, WhileStmt)):
        return _fold_stmt(node)
    if isinstance(node, (Literal, Var, UnaryOp, BinOp, LogicOp)):
        return _fold_expr(node)
    return node

from __future__ import annotations

import dataclasses
import math
from microvm.errors import CompileError
from microvm.optimizer import fold_constants
from microvm.parser import (
    AssignStmt,
    BinOp,
    BlockStmt,
    Expr,
    IfStmt,
    LetStmt,
    Literal,
    LogicOp,
    PrintStmt,
    ProgramAST,
    Stmt,
    UnaryOp,
    Var,
    WhileStmt,
    parse,
)


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str            # one of OPCODES
    arg: int | None    # None exactly when the opcode takes no argument


@dataclasses.dataclass
class Program:
    constants: list        # the constant pool
    names: list[str]       # variable names, slot order = declaration order
    instructions: list     # list[Instr]


BINOP_OPCODES: dict[str, str] = {
    "+": "ADD",
    "-": "SUB",
    "*": "MUL",
    "/": "DIV",
    "%": "MOD",
    "==": "EQ",
    "!=": "NE",
    "<": "LT",
    "<=": "LE",
    ">": "GT",
    ">=": "GE",
}


def _const_key(val: object) -> tuple[type, object]:
    if type(val) is float:
        if math.isnan(val):
            return (float, "nan")
        if val == 0.0:
            return (float, math.copysign(1.0, val), 0.0)
    return (type(val), val)


class _Compiler:
    def __init__(self) -> None:
        self.constants: list[object] = []
        self._const_map: dict[tuple[type, object], int] = {}
        self.names: list[str] = []
        self._name_map: dict[str, int] = {}
        self.instructions: list[Instr] = []

    def add_const(self, val: object) -> int:
        key = _const_key(val)
        if key in self._const_map:
            return self._const_map[key]
        idx = len(self.constants)
        self.constants.append(val)
        self._const_map[key] = idx
        return idx

    def emit(self, op: str, arg: int | None = None) -> int:
        idx = len(self.instructions)
        self.instructions.append(Instr(op, arg))
        return idx

    def patch(self, idx: int, target: int) -> None:
        old = self.instructions[idx]
        self.instructions[idx] = Instr(old.op, target)

    def collect_decls(self, stmts: list[Stmt]) -> None:
        for stmt in stmts:
            if isinstance(stmt, LetStmt):
                if stmt.name in self._name_map:
                    raise CompileError(f"Duplicate declaration of variable {stmt.name!r}")
                slot = len(self.names)
                self.names.append(stmt.name)
                self._name_map[stmt.name] = slot
            elif isinstance(stmt, BlockStmt):
                self.collect_decls(stmt.stmts)
            elif isinstance(stmt, IfStmt):
                self.collect_decls(stmt.then_block.stmts)
                if isinstance(stmt.else_branch, BlockStmt):
                    self.collect_decls(stmt.else_branch.stmts)
                elif isinstance(stmt.else_branch, IfStmt):
                    self.collect_decls([stmt.else_branch])
            elif isinstance(stmt, WhileStmt):
                self.collect_decls(stmt.body.stmts)

    def resolve_var(self, name: str) -> int:
        if name not in self._name_map:
            raise CompileError(f"Undeclared variable {name!r}")
        return self._name_map[name]

    def compile_program(self, ast: ProgramAST) -> Program:
        self.collect_decls(ast.stmts)
        for stmt in ast.stmts:
            self.compile_stmt(stmt)
        self.emit("HALT")
        return Program(self.constants, self.names, self.instructions)

    def compile_stmt(self, stmt: Stmt) -> None:
        if isinstance(stmt, (LetStmt, AssignStmt)):
            slot = self.resolve_var(stmt.name)
            self.compile_expr(stmt.expr)
            self.emit("STORE", slot)
        elif isinstance(stmt, PrintStmt):
            self.compile_expr(stmt.expr)
            self.emit("PRINT")
        elif isinstance(stmt, BlockStmt):
            for s in stmt.stmts:
                self.compile_stmt(s)
        elif isinstance(stmt, IfStmt):
            self._compile_if(stmt)
        elif isinstance(stmt, WhileStmt):
            self._compile_while(stmt)

    def _compile_if(self, stmt: IfStmt) -> None:
        self.compile_expr(stmt.cond)
        jfalse = self.emit("JUMP_IF_FALSE", 0)
        self.compile_stmt(stmt.then_block)
        if stmt.else_branch is None:
            self.patch(jfalse, len(self.instructions))
        else:
            jend = self.emit("JUMP", 0)
            self.patch(jfalse, len(self.instructions))
            self.compile_stmt(stmt.else_branch)
            self.patch(jend, len(self.instructions))

    def _compile_while(self, stmt: WhileStmt) -> None:
        loop_start = len(self.instructions)
        self.compile_expr(stmt.cond)
        jfalse = self.emit("JUMP_IF_FALSE", 0)
        self.compile_stmt(stmt.body)
        self.emit("JUMP", loop_start)
        self.patch(jfalse, len(self.instructions))

    def compile_expr(self, expr: Expr) -> None:
        if isinstance(expr, Literal):
            self.emit("CONST", self.add_const(expr.value))
        elif isinstance(expr, Var):
            self.emit("LOAD", self.resolve_var(expr.name))
        elif isinstance(expr, UnaryOp):
            self.compile_expr(expr.operand)
            self.emit("NEG" if expr.op == "-" else "NOT")
        elif isinstance(expr, BinOp):
            self.compile_expr(expr.left)
            self.compile_expr(expr.right)
            self.emit(BINOP_OPCODES[expr.op])
        elif isinstance(expr, LogicOp):
            self._compile_logic(expr)

    def _compile_logic(self, expr: LogicOp) -> None:
        if expr.op == "and":
            self.compile_expr(expr.left)
            jfalse1 = self.emit("JUMP_IF_FALSE", 0)
            self.compile_expr(expr.right)
            jfalse2 = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_const(True))
            jend = self.emit("JUMP", 0)
            false_pos = self.emit("CONST", self.add_const(False))
            self.patch(jfalse1, false_pos)
            self.patch(jfalse2, false_pos)
            self.patch(jend, len(self.instructions))
        else:
            self.compile_expr(expr.left)
            jfalse1 = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_const(True))
            jend1 = self.emit("JUMP", 0)
            right_pos = len(self.instructions)
            self.patch(jfalse1, right_pos)
            self.compile_expr(expr.right)
            jfalse2 = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_const(True))
            jend2 = self.emit("JUMP", 0)
            false_pos = self.emit("CONST", self.add_const(False))
            self.patch(jfalse2, false_pos)
            end_pos = len(self.instructions)
            self.patch(jend1, end_pos)
            self.patch(jend2, end_pos)


def compile_source(src: str, *, optimize: bool = False) -> Program:
    ast = parse(src)
    assert isinstance(ast, ProgramAST)
    if optimize:
        folded = fold_constants(ast)
        assert isinstance(folded, ProgramAST)
        ast = folded
    else:
        # Validate variable declarations and references before constant folding is skipped
        pass
    return _Compiler().compile_program(ast)

from __future__ import annotations

from microvm.compiler import Program
from microvm.errors import StepLimitError, VMRuntimeError

_UNASSIGNED = object()


def _is_num(val: object) -> bool:
    return type(val) in (int, float)


def _format_val(val: object) -> str:
    if type(val) is bool:
        return "true" if val else "false"
    if type(val) in (int, float):
        return str(val)
    if type(val) is str:
        return val
    raise VMRuntimeError(f"Unsupported value type {type(val).__name__}")


def _exec_arith(op: str, left: object, right: object) -> object:
    if op == "ADD" and type(left) is str and type(right) is str:
        return left + right
    if not (_is_num(left) and _is_num(right)):
        raise VMRuntimeError(f"{op} requires numeric operands")
    if op == "ADD":
        return left + right  # type: ignore[operator]
    if op == "SUB":
        return left - right  # type: ignore[operator]
    if op == "MUL":
        return left * right  # type: ignore[operator]
    if op == "DIV":
        if right == 0:
            raise VMRuntimeError("Division by zero")
        return float(left) / float(right)  # type: ignore[arg-type]
    if op == "MOD":
        if type(left) is not int or type(right) is not int:
            raise VMRuntimeError("MOD requires integer operands")
        if right == 0:
            raise VMRuntimeError("Modulo by zero")
        return left % right
    raise VMRuntimeError(f"Unknown arithmetic op {op}")


def _exec_cmp(op: str, left: object, right: object) -> bool:
    if op in ("EQ", "NE"):
        if _is_num(left) and _is_num(right):
            eq = left == right
        elif type(left) is type(right):
            eq = left == right
        else:
            eq = False
        return eq if op == "EQ" else not eq
    if (_is_num(left) and _is_num(right)) or (type(left) is str and type(right) is str):
        if op == "LT":
            return bool(left < right)  # type: ignore[operator]
        if op == "LE":
            return bool(left <= right)  # type: ignore[operator]
        if op == "GT":
            return bool(left > right)  # type: ignore[operator]
        if op == "GE":
            return bool(left >= right)  # type: ignore[operator]
    raise VMRuntimeError(f"{op} requires two numbers or two strings")


def _exec_unary(op: str, val: object) -> object:
    if op == "NEG":
        if not _is_num(val):
            raise VMRuntimeError("NEG requires a numeric operand")
        return -val  # type: ignore[operator]
    if op == "NOT":
        if type(val) is not bool:
            raise VMRuntimeError("NOT requires a boolean operand")
        return not val
    raise VMRuntimeError(f"Unknown unary op {op}")


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    if type(step_limit) is not int or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    instrs = program.instructions
    consts = program.constants
    names = program.names
    slots: list[object] = [_UNASSIGNED] * len(names)
    stack: list[object] = []
    output: list[str] = []
    ip = 0
    steps = 0
    n_instrs = len(instrs)

    while 0 <= ip < n_instrs:
        steps += 1
        if steps > step_limit:
            raise StepLimitError(f"Execution exceeded step limit of {step_limit}")
        ins = instrs[ip]
        op = ins.op
        arg = ins.arg
        ip += 1

        if op == "CONST":
            assert arg is not None
            stack.append(consts[arg])
        elif op == "LOAD":
            assert arg is not None
            val = slots[arg]
            if val is _UNASSIGNED:
                raise VMRuntimeError(f"Variable {names[arg]!r} read before assignment")
            stack.append(val)
        elif op == "STORE":
            assert arg is not None
            slots[arg] = stack.pop()
        elif op in ("ADD", "SUB", "MUL", "DIV", "MOD"):
            right = stack.pop()
            left = stack.pop()
            stack.append(_exec_arith(op, left, right))
        elif op in ("EQ", "NE", "LT", "LE", "GT", "GE"):
            right = stack.pop()
            left = stack.pop()
            stack.append(_exec_cmp(op, left, right))
        elif op in ("NEG", "NOT"):
            stack.append(_exec_unary(op, stack.pop()))
        elif op == "JUMP":
            assert arg is not None
            ip = arg
        elif op == "JUMP_IF_FALSE":
            assert arg is not None
            cond = stack.pop()
            if type(cond) is not bool:
                raise VMRuntimeError("Condition must be a boolean")
            if not cond:
                ip = arg
        elif op == "PRINT":
            output.append(_format_val(stack.pop()))
        elif op == "POP":
            stack.pop()
        elif op == "HALT":
            return output
        else:
            raise VMRuntimeError(f"Unknown opcode {op!r}")
    raise VMRuntimeError("Execution terminated without HALT")

from __future__ import annotations

import struct
import zlib
from microvm.compiler import Instr, Program
from microvm.errors import SerializationError
from microvm.opcodes import ARG_OPCODES, OPCODES, OPCODE_NUMBERS

MAGIC = b"MVM1"
VERSION = 1
NO_ARG = 0xFFFFFFFF

TAG_INT = 0x01
TAG_FLOAT = 0x02
TAG_STRING = 0x03
TAG_BOOL = 0x04

NUMBER_TO_OPCODE: dict[int, str] = {v: k for k, v in OPCODE_NUMBERS.items()}


def _pack_constant(val: object) -> bytes:
    if type(val) is bool:
        return struct.pack(">BB", TAG_BOOL, 1 if val else 0)
    if type(val) is int:
        if not (-(1 << 63) <= val <= (1 << 63) - 1):
            raise SerializationError(f"Integer constant {val} out of signed 64-bit range")
        return struct.pack(">Bq", TAG_INT, val)
    if type(val) is float:
        return struct.pack(">Bd", TAG_FLOAT, val)
    if type(val) is str:
        raw = val.encode("utf-8")
        if len(raw) > 0xFFFFFFFF:
            raise SerializationError("String constant too long")
        return struct.pack(">BI", TAG_STRING, len(raw)) + raw
    raise SerializationError(f"Unsupported constant type {type(val).__name__}")


def _pack_instruction(ins: Instr) -> bytes:
    if ins.op not in OPCODE_NUMBERS:
        raise SerializationError(f"Unknown opcode {ins.op!r}")
    op_num = OPCODE_NUMBERS[ins.op]
    takes_arg = ins.op in ARG_OPCODES
    if takes_arg:
        if ins.arg is None or type(ins.arg) is not int or not (0 <= ins.arg < NO_ARG):
            raise SerializationError(f"Invalid argument {ins.arg!r} for opcode {ins.op}")
        arg_val = ins.arg
    else:
        if ins.arg is not None:
            raise SerializationError(f"Opcode {ins.op} takes no argument, got {ins.arg!r}")
        arg_val = NO_ARG
    return struct.pack(">BI", op_num, arg_val)


def dumps(program: Program) -> bytes:
    body = bytearray()
    body.extend(struct.pack(">B", VERSION))

    if len(program.names) > 0xFFFF:
        raise SerializationError("Too many variable names")
    body.extend(struct.pack(">H", len(program.names)))
    for name in program.names:
        if not isinstance(name, str):
            raise SerializationError("Variable name must be a string")
        raw = name.encode("utf-8")
        if len(raw) > 0xFFFF:
            raise SerializationError("Variable name too long")
        body.extend(struct.pack(">H", len(raw)))
        body.extend(raw)

    if len(program.constants) > 0xFFFF:
        raise SerializationError("Too many constants")
    body.extend(struct.pack(">H", len(program.constants)))
    for c in program.constants:
        body.extend(_pack_constant(c))

    if len(program.instructions) > 0xFFFFFFFF:
        raise SerializationError("Too many instructions")
    body.extend(struct.pack(">I", len(program.instructions)))
    for ins in program.instructions:
        body.extend(_pack_instruction(ins))

    crc = zlib.crc32(body) & 0xFFFFFFFF
    return MAGIC + bytes(body) + struct.pack(">I", crc)


def _read_bytes(buf: bytes, pos: int, count: int) -> tuple[bytes, int]:
    if pos + count > len(buf):
        raise SerializationError("Unexpected end of binary data")
    return buf[pos : pos + count], pos + count


def _unpack_constants(buf: bytes, pos: int, count: int) -> tuple[list[object], int]:
    constants: list[object] = []
    for _ in range(count):
        raw_tag, pos = _read_bytes(buf, pos, 1)
        tag = raw_tag[0]
        if tag == TAG_INT:
            raw_val, pos = _read_bytes(buf, pos, 8)
            constants.append(struct.unpack(">q", raw_val)[0])
        elif tag == TAG_FLOAT:
            raw_val, pos = _read_bytes(buf, pos, 8)
            constants.append(struct.unpack(">d", raw_val)[0])
        elif tag == TAG_STRING:
            raw_len, pos = _read_bytes(buf, pos, 4)
            slen = struct.unpack(">I", raw_len)[0]
            raw_str, pos = _read_bytes(buf, pos, slen)
            try:
                constants.append(raw_str.decode("utf-8"))
            except UnicodeDecodeError as exc:
                raise SerializationError("Invalid UTF-8 in string constant") from exc
        elif tag == TAG_BOOL:
            raw_b, pos = _read_bytes(buf, pos, 1)
            bval = raw_b[0]
            if bval not in (0, 1):
                raise SerializationError(f"Invalid BOOL payload {bval}")
            constants.append(bool(bval))
        else:
            raise SerializationError(f"Unknown constant tag {tag:#x}")
    return constants, pos


def _unpack_instructions(buf: bytes, pos: int, count: int) -> tuple[list[Instr], int]:
    instructions: list[Instr] = []
    for _ in range(count):
        raw_ins, pos = _read_bytes(buf, pos, 5)
        op_num, arg_val = struct.unpack(">BI", raw_ins)
        if op_num not in NUMBER_TO_OPCODE:
            raise SerializationError(f"Unknown opcode number {op_num}")
        op_name = NUMBER_TO_OPCODE[op_num]
        takes_arg = op_name in ARG_OPCODES
        if takes_arg:
            if arg_val == NO_ARG:
                raise SerializationError(f"Missing argument for opcode {op_name}")
            instructions.append(Instr(op_name, arg_val))
        else:
            if arg_val != NO_ARG:
                raise SerializationError(f"Unexpected argument for opcode {op_name}")
            instructions.append(Instr(op_name, None))
    return instructions, pos


def loads(data: bytes) -> Program:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise SerializationError("Data must be bytes-like")
    buf = bytes(data)
    # Minimum size: 4 (magic) + 1 (version) + 2 (names) + 2 (consts) + 4 (instrs) + 4 (crc) = 17
    if len(buf) < 9:
        raise SerializationError("Data too short")
    if buf[:4] != MAGIC:
        raise SerializationError("Invalid magic header")
    expected_crc = struct.unpack(">I", buf[-4:])[0]
    body = buf[4:-4]
    actual_crc = zlib.crc32(body) & 0xFFFFFFFF
    if actual_crc != expected_crc:
        raise SerializationError("Checksum mismatch")

    pos = 0
    raw_ver, pos = _read_bytes(body, pos, 1)
    if raw_ver[0] != VERSION:
        raise SerializationError(f"Unsupported version {raw_ver[0]}")

    raw_ncount, pos = _read_bytes(body, pos, 2)
    ncount = struct.unpack(">H", raw_ncount)[0]
    names: list[str] = []
    for _ in range(ncount):
        raw_nlen, pos = _read_bytes(body, pos, 2)
        nlen = struct.unpack(">H", raw_nlen)[0]
        raw_name, pos = _read_bytes(body, pos, nlen)
        try:
            names.append(raw_name.decode("utf-8"))
        except UnicodeDecodeError as exc:
            raise SerializationError("Invalid UTF-8 in variable name") from exc

    raw_ccount, pos = _read_bytes(body, pos, 2)
    ccount = struct.unpack(">H", raw_ccount)[0]
    constants, pos = _unpack_constants(body, pos, ccount)

    raw_icount, pos = _read_bytes(body, pos, 4)
    icount = struct.unpack(">I", raw_icount)[0]
    instructions, pos = _unpack_instructions(body, pos, icount)

    if pos != len(body):
        raise SerializationError("Trailing bytes in payload")
    return Program(constants=constants, names=names, instructions=instructions)

from __future__ import annotations

from microvm.compiler import Program


def _format_const(val: object) -> str:
    if type(val) is bool:
        return "true" if val else "false"
    if type(val) in (int, float):
        return str(val)
    if type(val) is str:
        escaped = (
            val.replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\n", "\\n")
            .replace("\t", "\\t")
        )
        return f'"{escaped}"'
    return str(val)


def disassemble(program: Program) -> str:
    lines: list[str] = []
    for idx, ins in enumerate(program.instructions):
        if ins.arg is None:
            lines.append(f"{idx:04d} {ins.op}\n")
        elif ins.op == "CONST":
            c_str = _format_const(program.constants[ins.arg])
            lines.append(f"{idx:04d} {ins.op} {ins.arg}  ; {c_str}\n")
        else:
            lines.append(f"{idx:04d} {ins.op} {ins.arg}\n")
    return "".join(lines)

from __future__ import annotations

import argparse
import sys
from microvm.compiler import compile_source
from microvm.disassembler import disassemble
from microvm.errors import MicroVMError
from microvm.serializer import dumps, loads
from microvm.vm import execute


class _CLIArgumentParser(argparse.ArgumentParser):
    def error(self, message: str) -> None:
        raise ValueError(message)


def _positive_int(val: str) -> int:
    try:
        n = int(val)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("step-limit must be an integer") from exc
    if n <= 0:
        raise argparse.ArgumentTypeError("step-limit must be positive")
    return n


def _build_parser() -> argparse.ArgumentParser:
    parser = _CLIArgumentParser(prog="microvm", add_help=False)
    sub = parser.add_subparsers(dest="command", required=True)

    p_run = sub.add_parser("run", add_help=False)
    p_run.add_argument("file")
    p_run.add_argument("--optimize", action="store_true")
    p_run.add_argument("--step-limit", type=_positive_int, default=100_000)

    p_build = sub.add_parser("build", add_help=False)
    p_build.add_argument("file")
    p_build.add_argument("out")
    p_build.add_argument("--optimize", action="store_true")

    p_exec = sub.add_parser("exec", add_help=False)
    p_exec.add_argument("file")
    p_exec.add_argument("--step-limit", type=_positive_int, default=100_000)

    p_disasm = sub.add_parser("disasm", add_help=False)
    p_disasm.add_argument("file")

    return parser


def _run_cmd(ns: argparse.Namespace) -> int:
    try:
        with open(ns.file, "r", encoding="utf-8") as f:
            src = f.read()
    except OSError as exc:
        print(f"Error reading file: {exc}", file=sys.stderr)
        return 2
    prog = compile_source(src, optimize=ns.optimize)
    lines = execute(prog, step_limit=ns.step_limit)
    for line in lines:
        print(line)
    return 0


def _build_cmd(ns: argparse.Namespace) -> int:
    try:
        with open(ns.file, "r", encoding="utf-8") as f:
            src = f.read()
    except OSError as exc:
        print(f"Error reading file: {exc}", file=sys.stderr)
        return 2
    prog = compile_source(src, optimize=ns.optimize)
    data = dumps(prog)
    try:
        with open(ns.out, "wb") as f:
            f.write(data)
    except OSError as exc:
        print(f"Error writing file: {exc}", file=sys.stderr)
        return 2
    return 0


def _exec_cmd(ns: argparse.Namespace) -> int:
    try:
        with open(ns.file, "rb") as f:
            data = f.read()
    except OSError as exc:
        print(f"Error reading file: {exc}", file=sys.stderr)
        return 2
    prog = loads(data)
    lines = execute(prog, step_limit=ns.step_limit)
    for line in lines:
        print(line)
    return 0


def _disasm_cmd(ns: argparse.Namespace) -> int:
    try:
        with open(ns.file, "rb") as f:
            data = f.read()
    except OSError as exc:
        print(f"Error reading file: {exc}", file=sys.stderr)
        return 2
    prog = loads(data)
    sys.stdout.write(disassemble(prog))
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = _build_parser()
    try:
        ns = parser.parse_args(sys.argv[1:] if argv is None else argv)
    except (ValueError, SystemExit) as exc:
        print(f"Usage error: {exc}", file=sys.stderr)
        return 2

    try:
        if ns.command == "run":
            return _run_cmd(ns)
        if ns.command == "build":
            return _build_cmd(ns)
        if ns.command == "exec":
            return _exec_cmd(ns)
        if ns.command == "disasm":
            return _disasm_cmd(ns)
    except MicroVMError as exc:
        print(f"{type(exc).__name__}: {exc}", file=sys.stderr)
        return 3
    return 2


if __name__ == "__main__":
    sys.exit(main())

from __future__ import annotations

from microvm.parser import (
    AssignStmt,
    BinOp,
    BlockStmt,
    Expr,
    IfStmt,
    LetStmt,
    Literal,
    LogicOp,
    PrintStmt,
    ProgramAST,
    Stmt,
    UnaryOp,
    WhileStmt,
)


def _is_number(val: object) -> bool:
    return type(val) in (int, float)


def _fold_unary(node: UnaryOp, operand: Expr) -> Expr:
    if not isinstance(operand, Literal):
        return UnaryOp(node.op, operand, node.offset)
    val = operand.value
    if node.op == "-" and _is_number(val):
        return Literal(-val, node.offset)  # type: ignore[operator]
    if node.op == "not" and type(val) is bool:
        return Literal(not val, node.offset)
    return UnaryOp(node.op, operand, node.offset)


def _fold_arith(op: str, lv: object, rv: object, offset: int) -> Literal | None:
    if op == "+" and type(lv) is str and type(rv) is str:
        return Literal(lv + rv, offset)
    if not (_is_number(lv) and _is_number(rv)):
        return None
    if op == "+":
        return Literal(lv + rv, offset)  # type: ignore[operator]
    if op == "-":
        return Literal(lv - rv, offset)  # type: ignore[operator]
    if op == "*":
        return Literal(lv * rv, offset)  # type: ignore[operator]
    if op == "/":
        if rv == 0:
            return None
        return Literal(float(lv) / float(rv), offset)  # type: ignore[arg-type]
    if op == "%":
        if type(lv) is int and type(rv) is int and rv != 0:
            return Literal(lv % rv, offset)
    return None


def _fold_compare(op: str, lv: object, rv: object, offset: int) -> Literal | None:
    if op in ("==", "!="):
        if _is_number(lv) and _is_number(rv):
            eq = lv == rv
        elif type(lv) is type(rv):
            eq = lv == rv
        else:
            eq = False
        return Literal(eq if op == "==" else not eq, offset)
    if (_is_number(lv) and _is_number(rv)) or (type(lv) is str and type(rv) is str):
        if op == "<":
            return Literal(lv < rv, offset)  # type: ignore[operator]
        if op == "<=":
            return Literal(lv <= rv, offset)  # type: ignore[operator]
        if op == ">":
            return Literal(lv > rv, offset)  # type: ignore[operator]
        if op == ">=":
            return Literal(lv >= rv, offset)  # type: ignore[operator]
    return None


def _fold_binop(node: BinOp, left: Expr, right: Expr) -> Expr:
    if isinstance(left, Literal) and isinstance(right, Literal):
        lv, rv = left.value, right.value
        res = (
            _fold_arith(node.op, lv, rv, node.offset)
            if node.op in ("+", "-", "*", "/", "%")
            else _fold_compare(node.op, lv, rv, node.offset)
        )
        if res is not None:
            return res
    return BinOp(node.op, left, right, node.offset)


def _fold_logic(node: LogicOp, left: Expr, right: Expr) -> Expr:
    if isinstance(left, Literal) and type(left.value) is bool:
        if node.op == "and" and left.value is False:
            return Literal(False, node.offset)
        if node.op == "or" and left.value is True:
            return Literal(True, node.offset)
        if isinstance(right, Literal) and type(right.value) is bool:
            if node.op == "and":
                return Literal(left.value and right.value, node.offset)
            return Literal(left.value or right.value, node.offset)
    return LogicOp(node.op, left, right, node.offset)


def _fold_expr(expr: Expr) -> Expr:
    if isinstance(expr, UnaryOp):
        return _fold_unary(expr, _fold_expr(expr.operand))
    if isinstance(expr, BinOp):
        return _fold_binop(expr, _fold_expr(expr.left), _fold_expr(expr.right))
    if isinstance(expr, LogicOp):
        return _fold_logic(expr, _fold_expr(expr.left), _fold_expr(expr.right))
    return expr


def _fold_stmt(stmt: Stmt) -> Stmt:
    if isinstance(stmt, LetStmt):
        return LetStmt(stmt.name, _fold_expr(stmt.expr), stmt.offset)
    if isinstance(stmt, AssignStmt):
        return AssignStmt(stmt.name, _fold_expr(stmt.expr), stmt.offset)
    if isinstance(stmt, PrintStmt):
        return PrintStmt(_fold_expr(stmt.expr), stmt.offset)
    if isinstance(stmt, BlockStmt):
        return BlockStmt([_fold_stmt(s) for s in stmt.stmts], stmt.offset)
    if isinstance(stmt, IfStmt):
        cond = _fold_expr(stmt.cond)
        then_b = _fold_stmt(stmt.then_block)
        assert isinstance(then_b, BlockStmt)
        else_b = _fold_stmt(stmt.else_branch) if stmt.else_branch is not None else None
        assert else_b is None or isinstance(else_b, (BlockStmt, IfStmt))
        return IfStmt(cond, then_b, else_b, stmt.offset)
    if isinstance(stmt, WhileStmt):
        cond = _fold_expr(stmt.cond)
        body = _fold_stmt(stmt.body)
        assert isinstance(body, BlockStmt)
        return WhileStmt(cond, body, stmt.offset)
    return stmt


def fold_constants(node: object) -> object:
    if isinstance(node, ProgramAST):
        return ProgramAST([_fold_stmt(s) for s in node.stmts])
    if isinstance(node, (LetStmt, AssignStmt, PrintStmt, BlockStmt, IfStmt, WhileStmt)):
        return _fold_stmt(node)
    if isinstance(node, (Literal, Var, UnaryOp, BinOp, LogicOp)):
        return _fold_expr(node)
    return node

from __future__ import annotations

import dataclasses
import math
from microvm.errors import CompileError
from microvm.optimizer import fold_constants
from microvm.parser import (
    AssignStmt,
    BinOp,
    BlockStmt,
    Expr,
    IfStmt,
    LetStmt,
    Literal,
    LogicOp,
    PrintStmt,
    ProgramAST,
    Stmt,
    UnaryOp,
    Var,
    WhileStmt,
    parse,
)


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str            # one of OPCODES
    arg: int | None    # None exactly when the opcode takes no argument


@dataclasses.dataclass
class Program:
    constants: list        # the constant pool
    names: list[str]       # variable names, slot order = declaration order
    instructions: list     # list[Instr]


BINOP_OPCODES: dict[str, str] = {
    "+": "ADD",
    "-": "SUB",
    "*": "MUL",
    "/": "DIV",
    "%": "MOD",
    "==": "EQ",
    "!=": "NE",
    "<": "LT",
    "<=": "LE",
    ">": "GT",
    ">=": "GE",
}


def _const_key(val: object) -> tuple[type, object]:
    if type(val) is float:
        if math.isnan(val):
            return (float, "nan")
        if val == 0.0:
            return (float, math.copysign(1.0, val), 0.0)
    return (type(val), val)


class _Compiler:
    def __init__(self) -> None:
        self.constants: list[object] = []
        self._const_map: dict[tuple[type, object], int] = {}
        self.names: list[str] = []
        self._name_map: dict[str, int] = {}
        self.instructions: list[Instr] = []

    def add_const(self, val: object) -> int:
        key = _const_key(val)
        if key in self._const_map:
            return self._const_map[key]
        idx = len(self.constants)
        self.constants.append(val)
        self._const_map[key] = idx
        return idx

    def emit(self, op: str, arg: int | None = None) -> int:
        idx = len(self.instructions)
        self.instructions.append(Instr(op, arg))
        return idx

    def patch(self, idx: int, target: int) -> None:
        old = self.instructions[idx]
        self.instructions[idx] = Instr(old.op, target)

    def collect_decls(self, stmts: list[Stmt]) -> None:
        for stmt in stmts:
            if isinstance(stmt, LetStmt):
                if stmt.name in self._name_map:
                    raise CompileError(f"Duplicate declaration of variable {stmt.name!r}")
                slot = len(self.names)
                self.names.append(stmt.name)
                self._name_map[stmt.name] = slot
            elif isinstance(stmt, BlockStmt):
                self.collect_decls(stmt.stmts)
            elif isinstance(stmt, IfStmt):
                self.collect_decls(stmt.then_block.stmts)
                if isinstance(stmt.else_branch, BlockStmt):
                    self.collect_decls(stmt.else_branch.stmts)
                elif isinstance(stmt.else_branch, IfStmt):
                    self.collect_decls([stmt.else_branch])
            elif isinstance(stmt, WhileStmt):
                self.collect_decls(stmt.body.stmts)

    def resolve_var(self, name: str) -> int:
        if name not in self._name_map:
            raise CompileError(f"Undeclared variable {name!r}")
        return self._name_map[name]

    def compile_program(self, ast: ProgramAST) -> Program:
        self.collect_decls(ast.stmts)
        for stmt in ast.stmts:
            self.compile_stmt(stmt)
        self.emit("HALT")
        return Program(self.constants, self.names, self.instructions)

    def compile_stmt(self, stmt: Stmt) -> None:
        if isinstance(stmt, (LetStmt, AssignStmt)):
            slot = self.resolve_var(stmt.name)
            self.compile_expr(stmt.expr)
            self.emit("STORE", slot)
        elif isinstance(stmt, PrintStmt):
            self.compile_expr(stmt.expr)
            self.emit("PRINT")
        elif isinstance(stmt, BlockStmt):
            for s in stmt.stmts:
                self.compile_stmt(s)
        elif isinstance(stmt, IfStmt):
            self._compile_if(stmt)
        elif isinstance(stmt, WhileStmt):
            self._compile_while(stmt)

    def _compile_if(self, stmt: IfStmt) -> None:
        self.compile_expr(stmt.cond)
        jfalse = self.emit("JUMP_IF_FALSE", 0)
        self.compile_stmt(stmt.then_block)
        if stmt.else_branch is None:
            self.patch(jfalse, len(self.instructions))
        else:
            jend = self.emit("JUMP", 0)
            self.patch(jfalse, len(self.instructions))
            self.compile_stmt(stmt.else_branch)
            self.patch(jend, len(self.instructions))

    def _compile_while(self, stmt: WhileStmt) -> None:
        loop_start = len(self.instructions)
        self.compile_expr(stmt.cond)
        jfalse = self.emit("JUMP_IF_FALSE", 0)
        self.compile_stmt(stmt.body)
        self.emit("JUMP", loop_start)
        self.patch(jfalse, len(self.instructions))

    def compile_expr(self, expr: Expr) -> None:
        if isinstance(expr, Literal):
            self.emit("CONST", self.add_const(expr.value))
        elif isinstance(expr, Var):
            self.emit("LOAD", self.resolve_var(expr.name))
        elif isinstance(expr, UnaryOp):
            self.compile_expr(expr.operand)
            self.emit("NEG" if expr.op == "-" else "NOT")
        elif isinstance(expr, BinOp):
            self.compile_expr(expr.left)
            self.compile_expr(expr.right)
            self.emit(BINOP_OPCODES[expr.op])
        elif isinstance(expr, LogicOp):
            self._compile_logic(expr)

    def _compile_logic(self, expr: LogicOp) -> None:
        if expr.op == "and":
            self.compile_expr(expr.left)
            jfalse1 = self.emit("JUMP_IF_FALSE", 0)
            self.compile_expr(expr.right)
            jfalse2 = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_const(True))
            jend = self.emit("JUMP", 0)
            false_pos = self.emit("CONST", self.add_const(False))
            self.patch(jfalse1, false_pos)
            self.patch(jfalse2, false_pos)
            self.patch(jend, len(self.instructions))
        else:
            self.compile_expr(expr.left)
            jfalse1 = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_const(True))
            jend1 = self.emit("JUMP", 0)
            right_pos = len(self.instructions)
            self.patch(jfalse1, right_pos)
            self.compile_expr(expr.right)
            jfalse2 = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.add_const(True))
            jend2 = self.emit("JUMP", 0)
            false_pos = self.emit("CONST", self.add_const(False))
            self.patch(jfalse2, false_pos)
            end_pos = len(self.instructions)
            self.patch(jend1, end_pos)
            self.patch(jend2, end_pos)


def compile_source(src: str, *, optimize: bool = False) -> Program:
    ast = parse(src)
    assert isinstance(ast, ProgramAST)
    if optimize:
        folded = fold_constants(ast)
        assert isinstance(folded, ProgramAST)
        ast = folded
    else:
        # Validate variable declarations and references before constant folding is skipped
        pass
    return _Compiler().compile_program(ast)

from __future__ import annotations

from microvm.compiler import Program
from microvm.errors import StepLimitError, VMRuntimeError

_UNASSIGNED = object()


def _is_num(val: object) -> bool:
    return type(val) in (int, float)


def _format_val(val: object) -> str:
    if type(val) is bool:
        return "true" if val else "false"
    if type(val) in (int, float):
        return str(val)
    if type(val) is str:
        return val
    raise VMRuntimeError(f"Unsupported value type {type(val).__name__}")


def _exec_arith(op: str, left: object, right: object) -> object:
    if op == "ADD" and type(left) is str and type(right) is str:
        return left + right
    if not (_is_num(left) and _is_num(right)):
        raise VMRuntimeError(f"{op} requires numeric operands")
    if op == "ADD":
        return left + right  # type: ignore[operator]
    if op == "SUB":
        return left - right  # type: ignore[operator]
    if op == "MUL":
        return left * right  # type: ignore[operator]
    if op == "DIV":
        if right == 0:
            raise VMRuntimeError("Division by zero")
        return float(left) / float(right)  # type: ignore[arg-type]
    if op == "MOD":
        if type(left) is not int or type(right) is not int:
            raise VMRuntimeError("MOD requires integer operands")
        if right == 0:
            raise VMRuntimeError("Modulo by zero")
        return left % right
    raise VMRuntimeError(f"Unknown arithmetic op {op}")


def _exec_cmp(op: str, left: object, right: object) -> bool:
    if op in ("EQ", "NE"):
        if _is_num(left) and _is_num(right):
            eq = left == right
        elif type(left) is type(right):
            eq = left == right
        else:
            eq = False
        return eq if op == "EQ" else not eq
    if (_is_num(left) and _is_num(right)) or (type(left) is str and type(right) is str):
        if op == "LT":
            return bool(left < right)  # type: ignore[operator]
        if op == "LE":
            return bool(left <= right)  # type: ignore[operator]
        if op == "GT":
            return bool(left > right)  # type: ignore[operator]
        if op == "GE":
            return bool(left >= right)  # type: ignore[operator]
    raise VMRuntimeError(f"{op} requires two numbers or two strings")


def _exec_unary(op: str, val: object) -> object:
    if op == "NEG":
        if not _is_num(val):
            raise VMRuntimeError("NEG requires a numeric operand")
        return -val  # type: ignore[operator]
    if op == "NOT":
        if type(val) is not bool:
            raise VMRuntimeError("NOT requires a boolean operand")
        return not val
    raise VMRuntimeError(f"Unknown unary op {op}")


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    if type(step_limit) is not int or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    instrs = program.instructions
    consts = program.constants
    names = program.names
    slots: list[object] = [_UNASSIGNED] * len(names)
    stack: list[object] = []
    output: list[str] = []
    ip = 0
    steps = 0
    n_instrs = len(instrs)

    while 0 <= ip < n_instrs:
        steps += 1
        if steps > step_limit:
            raise StepLimitError(f"Execution exceeded step limit of {step_limit}")
        ins = instrs[ip]
        op = ins.op
        arg = ins.arg
        ip += 1

        if op == "CONST":
            assert arg is not None
            stack.append(consts[arg])
        elif op == "LOAD":
            assert arg is not None
            val = slots[arg]
            if val is _UNASSIGNED:
                raise VMRuntimeError(f"Variable {names[arg]!r} read before assignment")
            stack.append(val)
        elif op == "STORE":
            assert arg is not None
            slots[arg] = stack.pop()
        elif op in ("ADD", "SUB", "MUL", "DIV", "MOD"):
            right = stack.pop()
            left = stack.pop()
            stack.append(_exec_arith(op, left, right))
        elif op in ("EQ", "NE", "LT", "LE", "GT", "GE"):
            right = stack.pop()
            left = stack.pop()
            stack.append(_exec_cmp(op, left, right))
        elif op in ("NEG", "NOT"):
            stack.append(_exec_unary(op, stack.pop()))
        elif op == "JUMP":
            assert arg is not None
            ip = arg
        elif op == "JUMP_IF_FALSE":
            assert arg is not None
            cond = stack.pop()
