    assert toks[1] == Token("IDENT", "x", "x", 4)
    assert toks[2] == Token("OP", "=", "=", 6)
    assert toks[3] == Token("INT", "42", 42, 8)
    assert toks[4] == Token("OP", ";", ";", 10)
    assert toks[5] == Token("KEYWORD", "print", "print", 23)
    assert toks[6] == Token("STRING", 'hi\n\t"\\', 'hi\n\t"\\', 29)
