import ast
import pathlib

root = pathlib.Path(".")
files = list(root.glob("microvm/*.py")) + list(root.glob("tests/*.py"))
print(f"Checking {len(files)} files...")

forbidden = {"ast", "dis", "marshal", "pickle", "ctypes"}

for f in files:
    src = f.read_text(encoding="utf-8")
    tree = ast.parse(src, filename=str(f))
    if f.parent.name == "microvm":
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    assert alias.name.split(".")[0] not in forbidden, f"Forbidden import {alias.name} in {f}"
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    assert node.module.split(".")[0] not in forbidden, f"Forbidden import {node.module} in {f}"
            elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
                assert node.func.id not in {"compile", "eval", "exec"}, f"Forbidden call {node.func.id} in {f}"

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            start = node.body[0].lineno
            end = node.end_lineno
            total_span = node.end_lineno - node.lineno + 1
            body_span = end - start + 1
            if total_span > 60 or body_span > 60:
                print(f"LONG FUNCTION: {f}:{node.name} total={total_span} body={body_span}")
            for arg in node.args.args + node.args.kwonlyargs:
                if arg.arg != "self" and arg.annotation is None:
                    print(f"MISSING ARG ANNOTATION: {f}:{node.name}({arg.arg})")
            if node.returns is None:
                print(f"MISSING RETURN ANNOTATION: {f}:{node.name}")

test_funcs = [
    n.name for n in ast.walk(ast.parse(pathlib.Path("tests/test_microvm.py").read_text(encoding="utf-8")))
    if isinstance(n, ast.FunctionDef) and n.name.startswith("test_")
]
print(f"Test function count: {len(test_funcs)}")
